    def trap(self, height: List[int]) -> int:
        n = len(height)
        res = 0
        # dp存储每个位置的lmax, rmax
        # 通过从左往右和从右往左两次遍历便捷实现
        lmax, rmax = [0] * n, [0] * n
        lmax[0] = height[0]
        for i in range(1, n):
            lmax[i] = max(height[i], lmax[i - 1])
        rmax[n-1] = height[n-1]
        for i in range(n-2, -1, -1):
            rmax[i] = max(height[i], rmax[i + 1])
        # 根据高度差得到每个位置接的雨水
        for i in range(n):
            min_max = min(lmax[i], rmax[i])
            if min_max > height[i]:
                res += min_max - height[i]
        return res 这个dp可以优化为双指针，从两边往中间收缩，只使用常数空间边遍历边累加结果。 class Solution:
    def trap(self, height: List[int]) -> int:
        ans = 0
        left, right = 0, len(height) - 1
        leftMax = rightMax = 0

        while left < right:
            leftMax = max(leftMax, height[left])
            rightMax = max(rightMax, height[right])
            if height[left] < height[right]:
                ans += leftMax - height[left]
                left += 1
            else:
                ans += rightMax - height[right]
                right -= 1

        return ans 专题三 滑动窗口 3 无重复字符的最长子串 class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        # eg. abcabcbb
        # 滑动窗口: l始终从左往右移动.
        # 对于当前的l, r向右延伸试探, 如果添加了新的元素之后出现了重复, 则将l向右收缩直到无重复.
        n = len(s)
        if n == 0:
            return 0

        l, r = 0, 0
        res = 1
        alphabet = [s[0]]
        while l < n:
            r += 1
            if r == n:
                break
            while l < n and s[r] in alphabet:
                alphabet.remove(s[l])
                l += 1
            if l > r or l == n:
                break
            alphabet.append(s[r])
            res = max(res, r - l + 1)
        return res 438 找到字符串中所有字母异位词 字母异位词还是通过统计字母频率的方式去做。 class Solution:
