        n, m = len(s), len(p)
        p = sorted(p)
        res = []
        for l in range(n - m + 1):
            if sorted(s[l:l+m]) == p:
                res.append(l)
        return res 更好的思路应该是统计滑动窗口和子串每种字母的个数.（异位词使用字母个数） class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        n, m, res = len(s), len(p), []
        if n < m:
            return res
        p_cnt = [0] * 200
        s_cnt = [0] * 200

        for i in range(m):
            p_cnt[ord(p[i])] += 1

        l = 0
        for r in range(n):
            # 添加右边的字母, 删掉左边的
