    def subarraySum(self, nums: List[int], k: int) -> int:
        # 首先计算前缀和数组. 注意前缀和数组比原数组多一项s[0] = 0.
        s = [0] * (len(nums) + 1)
        for i, x in enumerate(nums):
            s[i + 1] = s[i] + x

        adict = defaultdict(int)
