    def minWindow(self, s: str, t: str) -> str:
        # 代码其实很直接.
        # 两个Counter利用>=处理"包含, 包括重复字符",
        # 伸展滑动窗口右指针, 如果成功包含, 则缩短左指针直到最小.
        cnt_s = Counter()
        cnt_t = Counter(t)

        ans_left, ans_right = -1, len(s) # 找到最短
        left = 0
        for right, c in enumerate(s):
            cnt_s[c] += 1
            while cnt_s >= cnt_t: # 涵盖
                if right - left < ans_right - ans_left:
                    ans_left, ans_right = left, right
                cnt_s[s[left]] -= 1
                left += 1
        return "" if ans_left < 0 else s[ans_left: ans_right + 1] 专题五 数组 53 最大子数组和 （解法一 前缀和） 要找到哪一段的和最大，首先转换成前缀和， 然后相当于求最大的差分。 一种思路是，固定当前的数，但是被减去的数维护为最小，这样遍历一遍即可得到最大的差分。 class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
