        for i, num in enumerate(nums):
            s[i+1] = s[i] + num
        maxval = -2147483647
        minval = 2147483647
        for i in range(1, len(nums) + 1):
            if s[i-1] < minval:
                minval = s[i-1]
            val = s[i] - minval
            if val > maxval:
