    def maxSubArray(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * (n + 1)
        dp[0] = nums[0]
        maxval = dp[0]

        for i in range(1, n):
            # 新元素一定被选择. 选择是是否包含前面的: 如果是拖油瓶(负值), 则轻装上阵.
            dp[i] = max(dp[i-1]+nums[i], nums[i])
            maxval = max(maxval, dp[i])
        return maxval 除此之外，这个动态规划由于每个元素都只取决于前一个，所以可以把数组优化为只用一个变量存储。 class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
