        # 利用队列实现“对应节点”的获取
        q = deque([(root.left, root.right)])
        while q:
            left, right = q.popleft()
            if not left and not right:
                continue
            elif not left or not right or left.val != right.val:
                return False
            else:
                q.append((left.left, right.right))
                q.append((left.right, right.left))
        return True 543 二叉树的直径 首先路径长度可以转化为经过的节点数减一， 然后转化成求以某个节点为根的树中最长路径的问题。 最长路径要么不经过根节点（对子树调用函数），要么经过根节点（转化为深度：L+R+1）。这二者通过self.ans取max得到最大值。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        # 转化为经过的节点数
        self.ans = 1
        def depth(node):
            if not node:
                return 0

            l = depth(node.left)
            r = depth(node.right)
            self.ans = max(self.ans, l + r + 1)
            return max(l, r) + 1

        depth(root)
        return self.ans - 1 # 转化回长度 102 二叉树的层序遍历 本来如果只是单纯层序列表的话直接入队出队就行， 但现在需要把同一层的放在一个子列表里，因此考虑添加深度信息和缓冲区，当前深度全部放完后再加入。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        res, cur_res = list(), list()
        q = deque([(root, 1)])
        cur = 1

        while q:
            node, node_dep = q.popleft()
            if not node:
                continue
            elif node_dep > cur:
                # 清空缓冲区, 再添加新元素
                res.append(cur_res)
                cur_res = list()
                cur += 1

            cur_res.append(node.val)
            q.append((node.left, node_dep + 1))
            q.append((node.right, node_dep + 1))

        if cur_res:
            res.append(cur_res)
        return res 108 将有序数组转换为平衡二叉搜索树 要建立平衡BST，方法是取区间中点作为根节点，然后对左右两段区间递归建立子树。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        def build(left, right):
            if left > right:
                return None

            mid = (left + right) // 2
            root = TreeNode(nums[mid])

            root.left = build(left, mid - 1)
            root.right = build(mid + 1, right)
            return root

        return build(0, len(nums) - 1) 98 验证二叉搜索树 最复杂的方式是每次都递归求左子树最大值、右子树最小值，并且递归验证每个树。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxVal(self, root):
        if root == None:
            return -float('inf')
        return max(root.val, self.maxVal(root.left), self.maxVal(root.right))

    def minVal(self, root):
        if root == None:
            return float('inf')
        return min(root.val, self.minVal(root.left), self.minVal(root.right))

    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        if root == None:
            return True
        if self.maxVal(root.left) >= root.val:
            return False
        if root.val >= self.minVal(root.right):
            return False
        return self.isValidBST(root.left) and self.isValidBST(root.right) 更好的方式是传递区间：根据每个节点的值，确定当前节点的值应该位于的区间，通过判断区间验证。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def validate(root, minVal, maxVal):
            if not root:
                return True
            if root.val <= minVal:
                return False
            if root.val >= maxVal:
                return False
            return validate(root.left, minVal, root.val) and validate(root.right, root.val, maxVal)

        return validate(root, -float('inf'), float('inf')) 230 二叉搜索树中第K小的元素 如果是一个数组，第K小只需要从前往后遍历到第K个。 而对于二叉搜索树，转成中序遍历即可从前往后遍历到第K个。为了在遍历到时直接返回、而不需要遍历整棵树，使用中序遍历的迭代写法。 中序遍历的迭代写法：需要先把左边全处理完，即从左记录到头才往回。栈中只需要记录往左的路径即可，这一点不同于根左右（记录待处理的右子树和左子树）。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def kthSmallest(self, root: Optional[TreeNode], k: int) -> int:
        stk = []
        curr = root
        while curr or stk:
            while curr:
                stk.append(curr)
                curr = curr.left
            curr = stk.pop()
            k -= 1
            if k == 0:
                return curr.val
            curr = curr.right 199 二叉树的右视图 基于层序遍历。层序遍历其实就是每次迭代时通过for循环取出当前层的所有节点（队列里的所有节点）。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        # 基于层序遍历
        if not root:
            return []

        q = deque([root])
        res = []

        while q:
            # 当前层的节点个数
            level_size = len(q)
            for i in range(level_size):
                node = q.popleft()
                if i == level_size - 1:
                    res.append(node.val)
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)

        return res 114 二叉树展开为链表 用了一个列表组织前序遍历，然后遍历列表改变属性。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        """
        Do not return anything, modify root in-place instead.
        """
        if not root:
            return

        def preorder(root):
            if not root:
                return []
            return [root] + preorder(root.left) + preorder(root.right)

        nodes = preorder(root)

        for i in range(len(nodes) - 1):
            nodes[i].left = None
            nodes[i].right = nodes[i + 1] 105 从前序和中序遍历序列构造二叉树 需要转成根据字符串的某些段构造二叉树，然后对于整个段执行初始函数。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        n = len(inorder)
        def build(l1, r1, l2, r2):
            if l1 > r1 or l2 > r2:
                return None

            root = preorder[l1]
            for i in range(n):
                if inorder[i] == root:
                    t = TreeNode(root)
                    t.left = build(l1 + 1, l1 + i - l2, l2, i - 1)
                    t.right = build(l1 + 1 + i - l2, r1, i + 1, r2)
                    return t

        return build(0, len(preorder) - 1, 0, len(preorder) - 1) 437 路径总和 III 求树中总和为targetSum的路径数量，起点任意。 这个问题很有趣：它其实来自“和为K的子数组”（子数组是连续的），而子数组问题我们知道有两种做法： (1) 朴素做法，定起点、遍历终点，计数和为K的情况。 (2) 前缀和做法，维护一个从前缀和到数量的哈希，通过前缀和的差为K确定和为K的子数组的个数。 这正对应了下述两种做法。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        if not root:
            return 0

        def countPaths(node, targetSum):
            # 计算从某节点开始的和为targerSum的路径数量.
            # 注意, 这个数量是和从其他节点开始的和为targetSum的路径数量无关的.
            if not node:
                return 0
            count = 1 if node.val == targetSum else 0
            count += countPaths(node.left, targetSum - node.val)
            count += countPaths(node.right, targetSum - node.val)
            return count

        # 对所有节点调用countPaths并求和
        return countPaths(root, targetSum) + self.pathSum(root.left, targetSum) + self.pathSum(root.right, targetSum) # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        self.count = 0
        self.premap = defaultdict(int)
        self.premap[0] = 1
        self.target = targetSum

        def dfs(node, cursum):
            if not node:
                return

            cursum += node.val
            self.count += self.premap[cursum - self.target]
            self.premap[cursum] += 1
            dfs(node.left, cursum)
            dfs(node.right, cursum)
            self.premap[cursum] -= 1
        # 不同起点的dfs不能互相影响, 所以要用回溯写法

        dfs(root, 0)
        return self.count 为了对比，将它们对应的“和为K的子数组”也列到下面。 事实上，唯一写法思路区别是递归和迭代。 def subarraySum(nums, k):
    count = 0
    n = len(nums)

    # 朴素做法：固定起点，累加找终点
    for start in range(n):
        curr_sum = 0
        for end in range(start, n):
            curr_sum += nums[end]
            if curr_sum == k:
                count += 1

    return count class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        premap = defaultdict(int)
        presum = 0
        premap[0] = 1

        count = 0

        for num in nums:
            # 如果presum - k出现过, 则它们的差为k.
            presum += num
            count += premap[presum - k]
            premap[presum] += 1

        return count 总之，对于数组，我们往往用迭代写法，因为递归写法往往是尾递归，没必要。 对于树和图，我们往往用递归写法，因为迭代写法需要手动维护栈或队列，写法略微复杂。 对于树和图的回溯问题，其实对应于各次迭代互相不影响的迭代循环。 236 二叉树的最近公共祖先 我们先考虑典型情况，然后再考虑为了实现典型情况所需的信息转移写法。 (1) p或q不在根的情况 如果左子树存在p或q节点 且 右子树存在p或q节点，则根为最近公共祖先。 如果二者中只有一者存在，则返回存在的那个。 如果都不存在，则返回None。 (2) p或q在根的情况 如果根不存在，返回None，否则一定返回根。 从上述来看，当前树的处理需要子树信息。因此应该用后序写法（左右根）。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        if not root or root == p or root == q:
            return root

        # 后序写法
        left = self.lowestCommonAncestor(root.left, p, q)
        right = self.lowestCommonAncestor(root.right, p, q)
        if left and right:
            return root
        else:
            return left or right 124 二叉树中的最大路径和 子树对整体的贡献只能“二选一”，但是路径要包含根。 # Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        self.res = -float('inf')

        def maxGain(node):
            if not node:
                return 0 # 不选

            # 以某个节点为根的最大贡献.
            l = max(maxGain(node.left), 0)
            r = max(maxGain(node.right), 0)
            pathSum = l + r + node.val
            self.res = max(self.res, pathSum)
            # 向上贡献时只能二选一.
            return max(l, r) + node.val

        maxGain(root)
        return self.res 专题九 图：DFS和BFS遍历 图这个专题是十分有趣的。最主要是DFS和BFS两种遍历方式。 为了两种写法都练得很熟练，我们往往可以把两种函数的接口设成高度相似的，这样可以无缝切换。 我们怎么样把图的DFS/BFS跟之前很好想的“树的DFS”给联系起来呢？ 根本在于“ 管好自己的，引出别人的。 ” 不管是任何DFS/BFS，自己的部分都只 处理自己 这个节点。与此同时，它们又要在末尾“ 引出邻居 ”节点供处理。这是核心逻辑。 除此之外，就是利用 visited 来防止重复判断/重复入队了。 注意仔细观察以下三个模板，逐行仔细看。这里模板多花点时间，早点想清楚，就是为了以后刷题少花点时间。 模板一：函数调用DFS “判断，标记，处理，邻居” def dfs ( node , visited , graph ): if node in visited : return # 1. 标记访问（关键！） visited . add ( node ) # 2. 处理当前节点（打印、统计等） print ( node ) # 3. 递归访问邻居 for neighbor in graph [ node ]: if neighbor not in visited : dfs ( neighbor , visited , graph ) 模板二：显式栈DFS （和队列BFS特别像！） def dfs_stack ( start , graph ): visited = set () stack = [ start ] while stack : node = stack . pop () if node in visited : continue visited . add ( node ) print ( node ) # 把未访问的邻居压入栈 for neighbor in graph [ node ]: if neighbor not in visited : stack . append ( neighbor ) 模板三：队列BFS BFS 只要无脑在入队时标记时就可以了，防止重复入队。 from collections import deque def bfs ( start , graph ): visited = set () queue = deque ([ start ]) visited . add ( start ) # 注意这里！！！BFS 只要无脑在入队时标记时就可以了，防止重复入队 while queue : node = queue . popleft () print ( node ) for neighbor in graph [ node ]: if neighbor not in visited : visited . add ( neighbor ) # 注意这里！！！同上 queue . append ( neighbor ) 把上述的邻接表换成网格，就变成了常考的网格模板。 # 方向数组（常用技巧） DIRS = [( 1 , 0 ), ( - 1 , 0 ), ( 0 , 1 ), ( 0 , - 1 )] def dfs_grid ( grid , r , c ): # 边界检查 + 访问检查（非0即1的网格通常直接将值改掉） if not ( 0 <= r < len ( grid ) and 0 <= c < len ( grid [ 0 ])): return if grid [ r ][ c ] != '1' : # 假设'1'是未访问的陆地 return grid [ r ][ c ] = '0' # 标记已访问 for dr , dc in DIRS : dfs_grid ( grid , r + dr , c + dc ) def bfs_grid ( grid , r , c ): from collections import deque q = deque ([( r , c )]) grid [ r ][ c ] = '0' while q : r , c = q . popleft () for dr , dc in DIRS : nr , nc = r + dr , c + dc if 0 <= nr < len ( grid ) and 0 <= nc < len ( grid [ 0 ]) and grid [ nr ][ nc ] == '1' : grid [ nr ][ nc ] = '0' q . append (( nr , nc )) 仔细做好上面的模板，下面两道题目完全是手到擒来。 经典题目： 200. 岛屿数量 class Solution : def numIslands ( self , grid : List [ List [ str ]]) -> int : DIR = [( 1 , 0 ), ( - 1 , 0 ), ( 0 , 1 ), ( 0 , - 1 )] def dfs ( r , c ): # 用于消灭掉一大片的海洋 if not ( 0 <= r < len ( grid ) and 0 <= c < len ( grid [ 0 ])): return if grid [ r ][ c ] != '1' : return grid [ r ][ c ] = '0' for dr , dc in DIR : dfs ( r + dr , c + dc ) def bfs ( r , c ): q = deque ([( r , c )]) grid [ r ][ c ] = '0' while q : row , col = q . popleft () for dr , dc in DIR : nr , nc = row + dr , col + dc if not ( 0 <= nr < len ( grid ) and 0 <= nc < len ( grid [ 0 ])): continue if grid [ nr ][ nc ] == '0' : continue q . append (( nr , nc )) grid [ nr ][ nc ] = '0' count = 0 for i in range ( len ( grid )): for j in range ( len ( grid [ 0 ])): if grid [ i ][ j ] == '1' : count += 1 bfs ( i , j ) return count 再练一道： 695. 岛屿的最大面积 。上面的模板以及上一道如果练熟了，这一道应该能很快地码出来（5分钟之类的）。 class Solution : def maxAreaOfIsland ( self , grid : List [ List [ int ]]) -> int : DIR = [( 1 , 0 ), ( - 1 , 0 ), ( 0 , 1 ), ( 0 , - 1 )] maxCount = 0 curCount = 0 def dfs ( r , c ): if not ( 0 <= r < len ( grid ) and 0 <= c < len ( grid [ 0 ])): return if not grid [ r ][ c ] == 1 : return grid [ r ][ c ] = 0 nonlocal curCount curCount += 1 for dr , dc in DIR : dfs ( r + dr , c + dc ) def bfs ( r , c ): q = deque ([( r , c )]) grid [ r ][ c ] = 0 nonlocal curCount curCount += 1 while q : row , col = q . popleft () for dr , dc in DIR : nr , nc = row + dr , col + dc if not ( 0 <= nr < len ( grid ) and 0 <= nc < len ( grid [ 0 ])): continue if not grid [ nr ][ nc ] == 1 : continue q . append (( nr , nc )) grid [ nr ][ nc ] = 0 curCount += 1 for i in range ( len ( grid )): for j in range ( len ( grid [ 0 ])): if grid [ i ][ j ] == 1 : curCount = 0 bfs ( i , j ) maxCount = max ( maxCount , curCount ) return maxCount 再来一道： 994. 腐烂的橘子 “打窝”然后让它扩散开来。这个就十分bfs了。 class Solution : def orangesRotting ( self , grid : List [ List [ int ]]) -> int : DIR = [( 1 , 0 ), ( - 1 , 0 ), ( 0 , 1 ), ( 0 , - 1 )] queue = deque ([]) for i in range ( len ( grid )): for j in range ( len ( grid [ 0 ])): if grid [ i ][ j ] == 2 : queue . append (( i , j , 0 )) res = 0 while queue : r , c , t = queue . popleft () for dr , dc in DIR : nr , nc = r + dr , c + dc if not ( 0 <= nr < len ( grid ) and 0 <= nc < len ( grid [ 0 ])): continue if grid [ nr ][ nc ] == 0 or grid [ nr ][ nc ] == 2 : continue grid [ nr ][ nc ] = 2 queue . append (( nr , nc , t + 1 )) res = max ( res , t + 1 ) for i in range ( len ( grid )): for j in range ( len ( grid [ 0 ])): if grid [ i ][ j ] == 1 : return - 1 return res 207. 课程表 / 210. 课程表 II 模版四：拓扑排序 拓扑排序其实也是基于BFS的。这里需要额外增加两个知识点： 需要知道怎么构建邻接表（pre->cur的有向边）。 需要记录并更新入度。 入队的永远是入度为0的点，出队永远用于更新邻接点的入度。 class Solution : def canFinish ( self , numCourses : int , prerequisites : List [ List [ int ]]) -> bool : graph = [[] for _ in range ( numCourses )] indegree = [ 0 ] * numCourses for cur , pre in prerequisites : graph [ pre ] . append ( cur ) indegree [ cur ] += 1 queue = deque ([ i for i in range ( numCourses ) if indegree [ i ] == 0 ]) count = 0 while queue : node = queue . popleft () count += 1 for neighbour in graph [ node ]: indegree [ neighbour ] -= 1 if indegree [ neighbour ] == 0 : queue . append ( neighbour ) return count == numCourses 208 实现Trie (前缀树) class Trie:

    def __init__(self):
        self.root = {}

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        # 表示存在恰好停在这里的单词
        node['$'] = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and '$' in node

    def startsWith(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def _find_node(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return None
            node = node[ch]
        return node


