    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target:
                return mid
            if nums[l] <= nums[mid]:
                # 这一段有序, 则可以通过和两个端点比较确定target是否在这一段内
                if nums[l] <= target < nums[mid]:
                    r = mid - 1
                else:
                    l = mid + 1
            else:
                if nums[mid] < target <= nums[r]:
                    l = mid + 1
                else:
                    r = mid - 1
        return -1 153 寻找旋转排序数组中的最小值 还是一样的道理，旋转排序数组通过判断哪半段区间是有序的，来解决问题。另外那一半无序的区间只需要通过移动端点逼近处理即可。 class Solution:
    def findMin(self, nums: List[int]) -> int:
        l, r = 0, len(nums) - 1
        minVal = nums[0]
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] < minVal:
                minVal = min(minVal, nums[mid])
            else:
                if nums[l] <= nums[mid]:
                    # 有序
                    minVal = min(minVal, nums[l])
                    l = mid + 1
                else:
                    minVal = min(minVal, nums[mid + 1])
                    r = mid - 1
        return minVal 4 寻找两个正序数组的中位数 这个的思想是，找到给两个数组切开的位置，使得切痕左边的整体，小于等于切痕右边的整体。并且，这两段整体大小相同。 实现方法是，将nums1左边的元素数量（切痕位置）作为二分查找的变量，然后通过左边整体的个数（两个数组总数的一半，向上取整）减去这个数量得到nums2左边的元素数量。 在二分基础上，加上了上取整、数组越界等细节。 class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # 在nums1某处切一刀, nums2某处切一刀
        # 使得两刀左边整体都比右边整体小.

        # 二分查找确定nums1要取的元素个数i, 然后左半部分元素个数应该恰好均分, 从而确定nums2要取的元素个数j.
        # 假如数组长度是5+6，则左半总共6个.
        # 假如数组长度是5+5, 则左半总共5个.
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1
        m, n = len(nums1), len(nums2)
        # 左半的元素总数, 上取整, 从而使得中位数基本上落入左半边
        total_left = (m + n + 1) // 2

        l, r = 0, m # i最少取0个, 最多取m个, 要确定所取个数
        while l <= r:
            i = (l + r) // 2
            j = total_left - i
            lmax_1 = float('-inf') if i == 0 else nums1[i - 1]
            rmin_1 = float('inf') if i == m else nums1[i]
            lmax_2 = float('-inf') if j == 0 else nums2[j - 1]
            rmin_2 = float('inf') if j == n else nums2[j]

            if lmax_1 <= rmin_2 and lmax_2 <= rmin_1: # 已找到
                if not (m + n) % 2:
                    return (max(lmax_1, lmax_2) + min(rmin_1, rmin_2)) / 2
                else:
                    return max(lmax_1, lmax_2)

            elif lmax_1 > rmin_2:
                r = i - 1
            else:
                l = i + 1

        return 0 专题12 栈 20 有效的括号 注意在使用下标前先做是否为空的判断，这个是容易漏掉的。 class Solution:
