    def __init__(self):
        # 两个结构各自实现栈和最小
        self.stk = []
        self.minStk = []

    def push(self, val: int) -> None:
        self.stk.append(val)
        i = bisect.bisect_left(self.minStk, val)
        self.minStk.insert(i, val)

    def pop(self) -> None:
        val = self.stk.pop()
        i = bisect.bisect_left(self.minStk, val)
        self.minStk.pop(i)

